class Solution:
    def minCostToMoveChips(self, position: List[int]) -> int:
        odd = 0
        even = 0

        for x in position:
            if x % 2 == 0:
                even += 1
            else:
                odd += 1

        # Gather on odd => pay for all even chips
        # Gather on even => pay for all odd chips
        return min(odd, even)

class Solution:
    def lemonadeChange(self, bills: List[int]) -> bool:
        five = 0
        ten = 0

        for bill in bills:
            if bill == 5:
                five += 1
            elif bill == 10:
                if five == 0:
                    return False
                five -= 1
                ten += 1
            else:  # bill == 20
                # Greedy: prefer 10 + 5 over 5 + 5 + 5
                if ten > 0 and five > 0:
                    ten -= 1
                    five -= 1
                elif five >= 3:
                    five -= 3
                else:
                    return False

        return True

import sys


def solve():
    data = list(map(int, sys.stdin.read().split()))
    n = data[0]
    vals = data[1:]

    v = [0] * n
    d = [0] * n
    p = [0] * n
    for i in range(n):
        v[i], d[i], p[i] = vals[3 * i], vals[3 * i + 1], vals[3 * i + 2]

    alive = [True] * n
    ans = []

    for i in range(n):
        if not alive[i]:
            continue

        # This child gets treated successfully
        ans.append(i + 1)

        # Snapshot the current surviving queue behind child i
        queue = [j for j in range(i + 1, n) if alive[j]]

        # Step 1: apply the decaying cry from the office
        cry = v[i]
        for j in queue:
            p[j] -= cry
            if cry > 0:
                cry -= 1

        # Step 2: process hallway chain reactions from front to back
        for idx, j in enumerate(queue):
            if not alive[j]:
                continue
            if p[j] < 0:
                alive[j] = False
                shock = d[j]
                for k in range(idx + 1, len(queue)):
                    nxt = queue[k]
                    if alive[nxt]:
                        p[nxt] -= shock

    print(len(ans))
    print(' '.join(map(str, ans)))


if __name__ == '__main__':
    solve()
